// === Tab: mySketch ===
//////////////
// Config   //
//////////////

// var imageUrl = "https://i.imgur.com/2R9AIW4.png"
var imageUrl = "https://i.imgur.com/gLrCDKq.jpg"

const coerceToImage = 0.9
const imageAvoidThreshold = 50
var numLines = 4000; // number of points
var canvasSize = { "x": 500, "y": 500 };
var pointSize = 1;
var pointColor = 'purple'
var trailLength = 7
var speed = 5.0
var noiseScale = 0.01
var eps = 0.001

//////////////
// State    //
//////////////

// Each line is an array of points.
// Each point has attributes x, y, xDir, yDir, and seed (all floats)
var lines = []

// Reference to image which we coerce the points to match
var img = null

//////////////
// Utils    //
//////////////

function seedLines(parts, num) {
  for (var lineIdx=0; lineIdx<numLines; ++lineIdx) {
    lines[lineIdx] = []
    lines[lineIdx][0] = {
      "x": random() * canvasSize.x,
      "y": random() * canvasSize.y,
      "xDir": random(lineIdx) > 0.5 ? 1.0 : -1.0,
      "yDir": random(lineIdx + 1000) > 0.5 ? 1.0 : -1.0,
			"seed": 0.0
    }
  }
}

// Credit: https://observablehq.com/@hellonearthis/curl-noise-function
function curlNoise(x, y, seed){
  //Find rate of change in X direction
  var n1 = noise(x + eps, y, seed);
  var n2 = noise(x - eps, y, seed);

  //Average to find approximate derivative
  var a = (n1 - n2)/(2 * eps);

  //Find rate of change in Y direction
  var n1 = noise(x, y + eps, seed);
  var n2 = noise(x, y - eps, seed);

  //Average to find approximate derivative
  var b = (n1 - n2)/(2 * eps);

  return [b, -a];
}

function advectPoints() {
  for (var lineIdx=0; lineIdx<numLines; ++lineIdx) {
    var pointList = lines[lineIdx]
    if (pointList.length == trailLength) { pointList.shift() }
    var lastPoint = pointList.slice(-1)[0]
    var curlNoiseVal = curlNoise(lastPoint.x * noiseScale, lastPoint.y * noiseScale, lastPoint.seed)

		const frozenThreshold = 0.0001
		const frozenMovement = 0.5
		if (curlNoiseVal[0] < frozenThreshold && curlNoiseVal[1] < frozenThreshold) {
			curlNoiseVal = [lastPoint.xDir * frozenMovement, lastPoint.yDir * frozenMovement]
			lastPoint.seed += 1.0 * lineIdx
		}
    var newPoint = {
      "x": lastPoint.x + curlNoiseVal[0] * speed * lastPoint.xDir,
      "y": lastPoint.y + curlNoiseVal[1] * speed * lastPoint.yDir,
      "xDir": lastPoint.xDir,
			"yDir": lastPoint.yDir,
			"seed": lastPoint.seed
    }
    // Pseudo collision detection (with bounds of canvas)
    if (newPoint.x < 0 || newPoint.x > canvasSize.x) {
      Object.assign(newPoint, {
        x: lastPoint.x - curlNoiseVal[0] * speed * lastPoint.xDir,
        xDir: lastPoint.xDir * -1
      })
    }

		var invert = newPoint.y < 0 || newPoint.y > canvasSize.y
		if (!invert) { invert = brightness(img.get(newPoint.x, newPoint.y)) < imageAvoidThreshold }
    if (invert) {
      Object.assign(newPoint, {
        y: lastPoint.y - curlNoiseVal[1] * speed * lastPoint.yDir,
        yDir: lastPoint.yDir * -1
      })
    }


		if (img.get) {
			const pixBrightness = map(brightness(img.get(newPoint.x, newPoint.y)), 0, 100, coerceToImage, 0.0);
			Object.assign(newPoint, {
				x: lerp(newPoint.x, lastPoint.x, pixBrightness),
				y: lerp(newPoint.y, lastPoint.y, pixBrightness),
			})
		}

    pointList.push(newPoint)
  }
}

///////////////
// Lifecycle //
///////////////

function preload() {
	img = loadImage(imageUrl);
	// console.log(img)
}

function setup() {
	img.resize(canvasSize.x, canvasSize.y);
  createCanvas(canvasSize.x, canvasSize.y);
  background(0);
  seedLines(lines);
}

function draw() {
  advectPoints()
	// seed += 1

  fill(0, 0, 0, 10);
  noStroke();
  rect(0,0,width,height);

  stroke(pointColor);
  strokeWeight(pointSize);

  for (var lineIdx=0; lineIdx<numLines; ++lineIdx) {
    var pointList = lines[lineIdx]
    for (var pointIdx = 1; pointIdx < pointList.length; pointIdx++) {
      var point1 = pointList[pointIdx - 1]
      var point2 = pointList[pointIdx]
      line(point1.x, point1.y, point2.x, point2.y)
    }
  }
}


// === Tab: util ===
function IX(x, y) {
	return x + y * nx;
}

// Bilinear sampling of a 2D field of 2D vectors
//==================================================================================================
function sample_2d(arr, x, y, res_x, res_y) {
	x = min(max(x, 0), res_x-2);
	y = min(max(y, 0), res_y-2);
	var ix = floor(x);
	var iy = floor(y);
	var s0 = arr[IX(ix,   iy  )];
	var s1 = arr[IX(ix+1, iy  )];
	var s2 = arr[IX(ix,   iy+1)];
	var s3 = arr[IX(ix+1, iy+1)];
	var tx = x - ix;
	var ty = y - iy;
	var sx0 = {"x": s0.x + (s1.x - s0.x) * tx, "y": s0.y + (s1.y - s0.y) * tx};
	var sx1 = {"x": s2.x + (s3.x - s2.x) * tx, "y": s2.y + (s3.y - s2.y) * tx};
	return {"x": sx0.x + (sx1.x - sx0.x) * ty, "y": sx0.y + (sx1.y - sx0.y) * ty};
}

// 3rd order Runge-Kutta particle advection (probably a bit overkill but I already had it)
//==================================================================================================
function advect_particle(p, vel_arr, res_x, res_y) {
	var h = 0.2;
	var steps = 1 / h;
	var ox = p.x;
	var oy = p.y;
	// RK3
	var k1, k2, k3, tx, ty;
	for (var s = 0; s < steps; ++s) {
		k1 = sample_2d(vel_arr, p.x, p.y, res_x, res_y);
		tx = p.x + k1.x * 0.5 * h;
		ty = p.y + k1.y * 0.5 * h;
		k2 = sample_2d(vel_arr, tx, ty, res_x, res_y);
		tx = tx + k2.x * 2.0 * h;
		ty = ty + k2.y * 2.0 * h;
		k3 = sample_2d(vel_arr, tx, ty, res_x, res_y);
		p.x += k3.x * h;
		p.y += k3.y * h;
	}

	p.len = sqrt(pow(p.x-ox,2) + pow(p.y-oy,2));

	if (p.x < 1) p.x = 1;
	if (p.x > width-2) p.x = width-2;
	if (p.y < 1) p.y = 1;
	if (p.y > height-2) p.y = height-2;
}

